INSERT INTO cache VALUES('laravel-cache-system_setting_brand_identity','a:3:{s:8:"ceo_name";s:16:"Okhna. TOUCH KIM";s:2:"en";a:6:{s:13:"company_story";s:382:"Established in 1999, Kim Mex Construction & Investment Co., Ltd. is a deeply respected and duly registered enterprise in the Kingdom of Cambodia. Over more than 25 years, we have evolved from a specialized engineering firm into a premier multi-disciplinary construction partner, delivering iconic infrastructure that stands the test of time while elevating the communities we serve.";s:11:"ceo_message";s:152:"Construction is not just about concrete and steel. It is about building trust, fostering communities, and leaving a legacy that stands the test of time.";s:7:"mission";s:135:"To bridge the gap between concept and reality through exceptional precision, military-grade safety, and sustainable building practices.";s:6:"vision";s:141:"To be the most trusted and innovative construction partner in Cambodia, setting the benchmark for excellence in architecture and engineering.";s:4:"goal";s:136:"To maintain long-term leadership in the Cambodian market through talent development, CMS investment, and a zero-accident safety records.";s:11:"values_list";a:1:{i:0;a:4:{s:5:"title";s:7:"HONESTY";s:11:"description";s:71:"Unwavering transparency and ethics in every contract and communication.";s:4:"icon";s:13:"lucide-shield";s:5:"image";s:48:"brand/core-values/01KS7KBWP90SW5SHRA9B72NHTM.png";}}}s:2:"km";a:6:{s:13:"company_story";s:1047:"បង្កើតឡើងក្នុងឆ្នាំ 1999 ក្រុមហ៊ុន គីម ម៉ិច ខនស្ត្រាសិន និង អ៊ិនវេសមេន ខូអិលធីឌី គឺជាសហគ្រាសដែលមានការចុះបញ្ជីត្រឹមត្រូវ និងគោរពយ៉ាងជ្រាលជ្រៅនៅក្នុងព្រះរាជាណាចក្រកម្ពុជា។ ក្នុងរយៈពេលជាង 25 ឆ្នាំ យើងបានវិវត្តន៍ពីក្រុមហ៊ុនវិស្វកម្មឯកទេសទៅជាដៃគូសាងសង់ពហុវិន័យឈានមុខគេ ដោយផ្តល់នូវហេដ្ឋារចនាសម្ព័ន្ធរូបសញ្ញាដែលឈរលើការសាកល្បងនៃពេលវេលាខណៈពេលដែលលើកកម្ពស់សហគមន៍ដែលយើងបម្រើ។";s:11:"ceo_message";s:415:"ការ​សាងសង់​មិន​មែន​ត្រឹម​តែ​បេតុង និង​ដែក​នោះ​ទេ។ វាគឺអំពីការកសាងទំនុកចិត្ត ជំរុញសហគមន៍ និងការបន្សល់ទុកនូវកេរដំណែលដែលឈរលើការសាកល្បងនៃពេលវេលា។";s:7:"mission";s:354:"ដើម្បីភ្ជាប់គម្លាតរវាងគំនិត និងការពិតតាមរយៈភាពជាក់លាក់ពិសេស សុវត្ថិភាពកម្រិតយោធា និងការអនុវត្តការកសាងប្រកបដោយនិរន្តរភាព។";s:6:"vision";s:420:"ដើម្បីធ្វើជាដៃគូសំណង់ប្រកបដោយភាពជឿជាក់ និងច្នៃប្រឌិតបំផុតនៅក្នុងប្រទេសកម្ពុជា កំណត់ស្តង់ដារសម្រាប់ឧត្តមភាពក្នុងវិស័យស្ថាបត្យកម្ម និងវិស្វកម្ម។";s:4:"goal";s:403:"ដើម្បីរក្សាភាពជាអ្នកដឹកនាំរយៈពេលវែងនៅក្នុងទីផ្សារកម្ពុជា តាមរយៈការអភិវឌ្ឍន៍ទេពកោសល្យ ការវិនិយោគ CMS និងកំណត់ត្រាសុវត្ថិភាពគ្មានគ្រោះថ្នាក់។";s:11:"values_list";a:1:{i:0;a:4:{s:5:"title";s:39:"ភាពស្មោះត្រង់";s:11:"description";s:200:"តម្លាភាព និងក្រមសីលធម៌មិនផ្លាស់ប្តូរនៅគ្រប់កិច្ចសន្យា និងទំនាក់ទំនង។";s:4:"icon";s:13:"lucide-shield";s:5:"image";s:48:"brand/core-values/01KS7KBWP90SW5SHRA9B72NHTM.png";}}}}',2095661975);
