INSERT INTO cache VALUES('laravel-cache-project_show_data_project-02-nbfsa-i_en','a:15:{s:2:"id";s:18:"project-02-nbfsa-i";s:5:"title";s:64:"NBFSA-I Non-Banking Financial Services Authority Office Building";s:4:"type";s:10:"Government";s:8:"location";s:83:"Building No. 168, Street 598, Sangkat Chrang Chamres 1, Khan Russey Keo, Phnom Penh";s:6:"status";s:7:"Ongoing";s:4:"date";s:13:"November 2026";s:6:"client";s:111:"អាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ NBFSA";s:10:"built_area";s:21:"14 floors | 6,900 m²";s:14:"contract_value";s:19:"Contact for Details";s:4:"year";s:19:"Jan 2025 - Nov 2026";s:9:"heroImage";s:32:"/images/projects/Thumbnail-1.jpg";s:9:"narrative";a:5:{s:11:"description";s:557:"គម្រោងសាងសង់ អគារការិយាល័យ អាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ NBFSA-I សម្រាប់ អាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ NBFSA មានទីតាំងនៅ អគារលេខ ១៦៨ ផ្លូវ ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឫស្សីកែវ រាជធានីភ្នំពេញ។";s:10:"background";s:7:"<p></p>";s:10:"objectives";s:7:"<p></p>";s:14:"design_concept";s:7:"<p></p>";s:21:"engineering_narrative";s:7:"<p></p>";}s:5:"scope";s:645:"<ul><li><p>ម្ចាស់គម្រោង: អាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ NBFSA</p></li><li><p>ទីតាំងសាងសង់: អគារលេខ ១៦៨ ផ្លូវ ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឫស្សីកែវ រាជធានីភ្នំពេញ</p></li><li><p>តម្លៃសាងសង់: $4,930,000.00</p></li><li><p>ផ្ទៃក្រឡា: 6,900 m²</p></li><li><p>ចំនួនជាន់: 14ជាន់</p></li><li><p>រយៈពេល: 22 ខែ</p></li></ul>";s:6:"images";a:0:{}s:7:"related";a:3:{i:0;a:4:{s:2:"id";s:17:"project-01-mef-09";s:5:"title";s:42:"Ministry of Economy Office Building MEF-09";s:4:"type";s:10:"Government";s:5:"image";s:32:"/images/projects/Thumbnail-5.jpg";}i:1;a:4:{s:2:"id";s:15:"project-03-nspc";s:5:"title";s:44:"NSPC Social Security Council Office Building";s:4:"type";s:10:"Government";s:5:"image";s:32:"/images/projects/Thumbnail-5.jpg";}i:2;a:4:{s:2:"id";s:25:"project-04-smart-building";s:5:"title";s:45:"Royal University of Phnom Penh Smart Building";s:4:"type";s:5:"Slope";s:5:"image";s:32:"/images/projects/Thumbnail-5.jpg";}}}',1780