INSERT INTO system_settings VALUES('019e4f0f-0613-70e3-ae3c-89f855bc769d','brand_identity','{"ceo_name":"Okhna. TOUCH KIM","en":{"company_story":"Established in 1999, Kim Mex Construction & Investment Co., Ltd. is a deeply respected and duly registered enterprise in the Kingdom of Cambodia. Over more than 25 years, we have evolved from a specialized engineering firm into a premier multi-disciplinary construction partner, delivering iconic infrastructure that stands the test of time while elevating the communities we serve.","ceo_message":"Construction is not just about concrete and steel. It is about building trust, fostering communities, and leaving a legacy that stands the test of time.","mission":"To bridge the gap between concept and reality through exceptional precision, military-grade safety, and sustainable building practices.","vision":"To be the most trusted and innovative construction partner in Cambodia, setting the benchmark for excellence in architecture and engineering.","goal":"To maintain long-term leadership in the Cambodian market through talent development, CMS investment, and a zero-accident safety records.","values_list":[{"title":"HONESTY","description":"Unwavering transparency and ethics in every contract and communication.","icon":"lucide-shield","image":"brand\/core-values\/01KS7KBWP90SW5SHRA9B72NHTM.png"}]},"km":{"company_story":"\u1794\u1784\u17d2\u1780\u17be\u178f\u17a1\u17be\u1784\u1780\u17d2\u1793\u17bb\u1784\u1786\u17d2\u1793\u17b6\u17c6 1999 \u1780\u17d2\u179a\u17bb\u1798\u17a0\u17ca\u17bb\u1793 \u1782\u17b8\u1798 \u1798\u17c9\u17b7\u1785 \u1781\u1793\u179f\u17d2\u178f\u17d2\u179a\u17b6\u179f\u17b7\u1793 \u1793\u17b7\u1784 \u17a2\u17ca\u17b7\u1793\u179c\u17c1\u179f\u1798\u17c1\u1793 \u1781\u17bc\u17a2\u17b7\u179b\u1792\u17b8\u178c\u17b8 \u1782\u17ba\u1787\u17b6\u179f\u17a0\u1782\u17d2\u179a\u17b6\u179f\u178a\u17c2\u179b\u1798\u17b6\u1793\u1780\u17b6\u179a\u1785\u17bb\u17c7\u1794\u1789\u17d2\u1787\u17b8\u178f\u17d2\u179a\u17b9\u1798\u1