INSERT INTO services VALUES('019e4f0f-061d-72dd-8898-32bcb73af990','{"en":"Construction","km":"ការសាងសង់"}','construction','lucide-hammer','{"en":"World-class building and civil engineering solutions. We deliver robust structures tailored to residential, commercial, and industrial needs.","km":"ដំណោះស្រាយវិស្វកម្មស៊ីវិល និងសំណង់កម្រិតពិភពលោក។ យើងផ្តល់ជូននូវរចនាសម្ព័ន្ធរឹងមាំតម្រូវតាមតម្រូវការលំនៅដ្ឋាន ពាណិជ្ជកម្ម និងឧស្សាហកម្ម។"}','{"en":"World-class building and civil engineering solutions. We deliver robust structures tailored to residential, commercial, and industrial needs.","km":"ដំណោះស្រាយវិស្វកម្មស៊ីវិល និងសំណង់កម្រិតពិភពលោក។ យើងផ្តល់ជូននូវរចនាសម្ព័ន្ធរឹងមាំតម្រូវតាមតម្រូវការលំនៅដ្ឋាន ពាណិជ្ជកម្ម និងឧស្សាហកម្ម។"}','/images/projects/Thumbnail-4.jpg','[{"name":"Civil Engineering"},{"name":"Building Structure"},{"name":"MEP Systems"},{"name":"Industrial Plants"}]',2,1,'2026-05-22 09:40:45','2026-05-22 09:40:45');
INSERT INTO services VALUES('019e4f0f-061f-71bc-8904-1bb98f43623d','{"en":"Project Management","km":"ការគ្រប់គ្រងគម្រោង"}','project-management','lucide-settings','{"en":"Comprehensive oversight and strategic advisory ensuring on-time, on-budget delivery. We combine rigorous on-field management with technical and financ...","km":"ការត្រួតពិនិត្យដ៏ទូលំទូលាយ និងការផ្តល់ប្រឹក្សាយុទ្ធសាស្រ្តធានាបាននូវការដឹកជញ្ជូនទាន់ពេល និងចំថវិកា។ យើងរួមបញ្ចូលការគ្រប់គ្រងយ៉ាងតឹងរ៉ឹងជាមួយចំណេះដឹងផ្..."}','{"en":"Comprehensive oversight and strategic advisory ensuring on-time, on-budget delivery. We combine rigorous on-field management with technical and financial insights.","km":"ការត្រួតពិនិត្យដ៏ទូលំទូលាយ និងការផ្តល់ប្រឹក្សាយុទ្ធសាស្រ្តធានាបាននូវការដឹកជញ្ជូនទាន់ពេល និងចំថវិកា។ យើងរួមបញ្ចូលការគ្រប់គ្រងយ៉ាងតឹងរ៉ឹងជាមួយចំណេះដឹងផ្នែកបច្ចេកទេស និងហិរញ្ញវត្ថុ។"}','/images/projects/Thumbnail-5.jpg','[{"name":"Cost Control & Value Engineering"},{"name":"Feasibility Studies"},{"name":"Quality & Safety Compliance"},{"name":"Regulatory Advice"}]',3,1,'2026-05-22 09:40:45','2026-05-22 09:40:45');
INSERT INTO services VALUES('019e4f0f-0621-7262-b85d-d378de4cfafe','{"en":"Infrastructure","km":"ហេដ្ឋារចនាសម្ព័ន្ធ"}','infrastructure','lucide-truck','{"en":"Developing critical infrastructure including roads, bridges, and public utilities. We build foundation for national growth.","km":"ការអភិវឌ្ឍហេដ្ឋារចនាសម្ព័ន្ធសំខាន់ៗរួមមាន ផ្លូវ ស្ពាន និងឧបករណ៍ប្រើប្រាស់សាធារណៈ។ យើងកសាងមូលដ្ឋានគ្រឹះសម្រាប់កំណើនជាតិ។"}','{"en":"Developing critical infrastructure including roads, bridges, and public utilities. We build foundation for national growth.","km":"ការអភិវឌ្ឍហេដ្ឋារចនាសម្ព័ន្ធសំខាន់ៗរួមមាន ផ្លូវ ស្ពាន និងឧបករណ៍ប្រើប្រាស់សាធារណៈ។ យើងកសាងមូលដ្ឋានគ្រឹះសម្រាប់កំណើនជាតិ។"}','/images/projects/Thumbnail-6.jpg','[{"name":"Road & Bridge Construction"},{"name":"Public Utility Networks"},{"name":"Slope Protection"},{"name":"Land Reclamation"}]',4,0,'2026-05-22 09:40:45','2026-05-25 09:53:42');
