INSERT INTO job_postings VALUES('019e4f0f-06af-703c-865f-32238e575b24','{"en":"Senior Project Manager","km":"អ្នកគ្រប់គ្រងគម្រោងជាន់ខ្ពស់"}','senior-project-manager',NULL,'{"en":"Phnom Penh","km":"ភ្នំពេញ"}','FULL_TIME','{"en":"Leading large-scale construction projects from inception to completion.","km":"ដឹកនាំគម្រោងសាងសង់ខ្នាតធំចាប់ពីការចាប់ផ្តើមរហូតដល់ការបញ្ចប់។"}','{"en":"Bachelor''s degree in Civil Engineering.\nStrong leadership and communication skills.\nProficiency in project management software.","km":"បរិញ្ញាបត្រផ្នែកវិស្វកម្មស៊ីវិល។\nជំនាញដឹកនាំនិងទំនាក់ទំនងខ្លាំង។\nជំនាញក្នុងកម្មវិធីគ្រប់គ្រងគម្រោង។"}','{"en":"Health insurance.\nPerformance bonuses.\nProfessional development opportunities.","km":"ធានារ៉ាប់រងសុខភាព។\nប្រាក់រង្វាន់ការងារ។\nឱកាសអភិវឌ្ឍន៍វិជ្ជាជីវៈ។"}',1,NULL,'{"en":"5-10 Years","km":"៥-១០ ឆ្នាំ"}','{"en":"Competitive","km":"ប្រកួតប្រជែង"}','{"en":"Manage project budgets and timelines.\nCoordinate with subcontractors and engineers.\nEnsure safety and quality compliance.","km":"<ul><li>គ្រប់គ្រងថវិកានិងពេលវេលាគម្រោង។</li><li>សម្របសម្រួលជាមួយអ្នកម៉ៅការបន្តនិងវិស្វករ។</li><li>ធានាបាននូវការអនុលោមតាមសុវត្ថិភាពនិងគុណភាព។</li></ul>"}','2026-05-22 09:40:45','2026-05-22 09:40:45');
INSERT INTO job_postings VALUES('019e4f0f-06b1-70e0-bb38-4d699f63ef74','{"en":"Site Engineer","km":"វិស្វករការដ្ឋាន"}','site-engineer',NULL,'{"en":"Siem Reap","km":"សៀមរាប"}','FULL_TIME','{"en":"Overseeing day-to-day operations on construction sites.","km":"ត្រួតពិនិត្យប្រតិបត្តិការប្រចាំថ្ងៃនៅការដ្ឋានសំណង់។"}','{"en":"Degree in Civil Engineering or related field.\nPractical experience in site supervision.\nProblem-solving mindset.","km":"សញ្ញាបត្រផ្នែកវិស្វកម្មស៊ីវិលឬជំនាញពាក់ព័ន្ធ។\nបទពិសោធន៍ជាក់ស្តែងក្នុងការត្រួតពិនិត្យការដ្ឋាន។\nផ្នត់គំនិតដោះស្រាយបញ្ហា។"}','{"en":"Accommodation allowance.\nSkills training.\nCareer growth track.","km":"ប្រាក់ឧបត្ថម្ភការស្នាក់នៅ។\nការបណ្តុះបណ្តាលជំនាញ។\nផ្លូវកំណើនអាជីព។"}',1,NULL,'{"en":"2-5 Years","km":"២-៥ ឆ្នាំ"}','{"en":"Negotiable","km":"ចរចា"}','{"en":"Supervise site labor and subcontractors.\nTechnical review of architectural blueprints.\nReport progress to Project Managers.","km":"<ul><li>ត្រួតពិនិត្យកម្លាំងពលកម្មនិងអ្នកម៉ៅការបន្ត។</li><li>ពិនិត្យបច្ចេកទេសលើប្លង់ស្ថាបត្យកម្ម។</li><li>រាយការណ៍វឌ្ឍនភាពទៅអ្នកគ្រប់គ្រងគម្រោង។</li></ul>"}','2026-05-22 09:40:45','2026-05-22 09:40:45');
INSERT INTO news_articles VALUES('019e4f0f-06a8-703d-ac8c-9a08a31c4cfa','{"en":"Green Urban Initiative 2026: A Sustainability Milestone","km":"គំនិតផ្តួចផ្តើមទីក្រុងបៃតង ២០២៦៖ ដំណាក់កាលថ្មីនៃនិរន្តរភាព"}','green-initiative','{"en":"Kimmex has been officially awarded the 2026 Urban Sustainability Contract, a $50M initiative to transform city transport.","km":"ក្រុមហ៊ុន Kimmex ត្រូវបានផ្តល់កិច្ចសន្យានិរន្តរភាពទីក្រុងឆ្នាំ ២០២៦ ជាផ្លូវការ ដែលជាគម្រោង ៥០លានដុល្លារ ដើម្បីផ្លាស់ប្តូរការដឹកជញ្ជូនក្នុងទីក្រុង។"}','{"en":"\n                        <p>In a significant milestone for sustainable development in Southeast Asia, Kimmex Construction & Investment Co., Ltd. has announced its leadership in the <strong>Green Urban Initiative 2026</strong>. This project aims to integrate smart grid technology with carbon-neutral construction materials across major metropolitan routes.</p>\n                        \n                        <figure class=\"my-12\">\n                            <img src=\"/images/projects/Thumbnail-6.jpg\" class=\"rounded-3xl shadow-2xl w-full\" alt=\"Green Hub Project\" />\n                            <figcaption class=\"text-xs text-center text-gray-400 mt-4 uppercase tracking-widest\">Architectural Visualization of the 2026 Green Hub</figcaption>\n                        </figure>\n\n                        <p>Our team of engineers has spent over 18 months developing a proprietary \"Eco-Concrete\" blend that reduces CO2 emissions by 40% compared to traditional standards. This innovation is at the heart of the new project.</p>\n                        \n                        <div class=\"my-12 aspect-video rounded-3xl overflow-hidden shadow-2xl\">\n                            <iframe class=\"w-full h-full\" src=\"https://www.youtube.com/embed/dQw4w9WgXcQ\" title=\"Project Overview\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>\n                        </div>\n\n                        <p>Beyond materials, the initiative also includes a massive reforestation effort within urban centers, integrating living vertical gardens into infrastructure supports.</p>\n                    ","km":"\n                        <p>ក្នុងដំណាក់កាលដ៏សំខាន់សម្រាប់ការអភិវឌ្ឍប្រកបដោយចីរភាពនៅអាស៊ីអាគ្នេយ៍ ក្រុមហ៊ុន Kimmex Construction & Investment Co., Ltd. បានប្រកាសពីភាពជាអ្នកដឹកនាំរបស់ខ្លួនក្នុង <strong>គំនិតផ្តួចផ្តើមទីក្រុងបៃតង ២០២៦</strong>។</p>\n                    "}',NULL,'2026-05-22 09:40:45','{"en":"Infrastructure"}',NULL,NULL,1,NULL,NULL,'{"en":"Dr. Sok Chea","km":"បណ្ឌិត សុខ ជា"}','["\/images\/projects\/Thumbnail-1.jpg","\/images\/projects\/Thumbnail-2.jpg","\/images\/projects\/Thumbnail-3.jpg","\/images\/projects\/Thumbnail-4.jpg"]',0,'{"en":"5 min read","km":"៥ នាទី"}',NULL,'2026-05-22 09:40:45','2026-05-22 09:40:45',1,NULL);
INSERT INTO news_articles VALUES('019e4f0f-06ab-7266-9783-38b96c26eb8f','{"en":"Kimmex Achieves 1 Million Safe Man-Hours on SkyTower Project","km":"ក្រុមហ៊ុន Kimmex សម្រេចបាន ១ លានម៉ោងការងារប្រកបដោយសុវត្ថិភាពលើគម្រោង SkyTower"}','safety-milestone-skytower','{"en":"A testament to our unwavering commitment to employee well-being and rigorous safety protocols.","km":"សក្ខីភាពមួយចំពោះការប្តេជ្ញាចិត្តមិនងាករេរបស់យើងចំពោះសុខុមាលភាពបុគ្គលិក និងពិធីសារសុវត្ថិភាពដ៏តឹងរឹង។"}','{"en":"\n                        <p>Safety is the cornerstone of every Kimmex project. We are proud to announce that the SkyTower development team has surpassed <strong>one million man-hours</strong> without a single lost-time injury (LTI).</p>\n                    ","km":"<p>សុវត្ថិភាពគឺជាមូលដ្ឋានគ្រឹះនៃរាល់គម្រោងរបស់ Kimmex។</p>"}',NULL,'2026-05-22 09:40:45','{"en":"Safety"}',NULL,NULL,0,NULL,NULL,'{"en":"HSE Dept","km":"ផ្នែកសុវត្ថិភាព"}','["\/images\/projects\/Thumbnail-5.jpg","\/images\/projects\/Thumbnail-7.jpg"]',0,'{"en":"3 min read","km":"៣ នាទី"}',NULL,'2026-05-22 09:40:45','2026-05-22 09:40:45',1,NULL);
