INSERT INTO documents VALUES('019e4f0f-0687-72d9-a617-b04dcf0a2c55','{"en":"Site Safety & Risk Management Protocol","km":"Site Safety & Risk Management Protocol (Khmer)"}','{"en":"Updated safety requirements for active worksites including high-visibility PPE, harness regulations, and evacuation muster points.","km":"Updated safety requirements for active worksites including high-visibility PPE, harness regulations, and evacuation muster points. (Khmer)"}','documents/dummy-site-safety-risk-management-protocol.pdf','4.2 MB','PDF',NULL,'Safety Manuals',NULL,1,0,'2026-05-22 09:40:45','2026-05-22 09:40:45','site-safety-risk-management-protocol',1,10,1);
INSERT INTO documents VALUES('019e4f0f-0688-7356-a233-610c1f8ecf82','{"en":"Ministry of Infrastructure Complex: Case Study","km":"Ministry of Infrastructure Complex: Case Study (Khmer)"}','{"en":"A detailed post-mortem on the delivery of the 15-story government complex, detailing challenges overcome in deep foundation piling.","km":"A detailed post-mortem on the delivery of the 15-story government complex, detailing challenges overcome in deep foundation piling. (Khmer)"}','documents/dummy-ministry-of-infrastructure-complex-case-study.pdf','12.5 MB','PDF',NULL,'Case Studies',NULL,1,0,'2026-05-22 09:40:45','2026-05-22 09:40:45','ministry-of-infrastructure-complex-case-study',0,11,1);
