PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar, "email" varchar, "email_verified_at" datetime, "image" varchar, "role" varchar not null default 'EDITOR', "password" varchar, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" varchar not null, "user_id" integer, "action" varchar not null, "entity" varchar not null, "entityId" varchar not null, "details" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "project_images" ("id" varchar not null, "url" varchar not null, "caption" varchar, "projectId" varchar not null, "created_at" datetime, "updated_at" datetime, "sort_order" integer not null default '0', foreign key("projectId") references "projects"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "inquiries" ("id" varchar not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "subject" varchar, "message" text not null, "status" varchar not null default 'NEW', "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "attachment_url" varchar, primary key ("id"));
CREATE TABLE IF NOT EXISTS "system_settings" ("id" varchar not null, "key" varchar not null, "value" text not null, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "services" ("id" varchar not null, "title" text, "slug" varchar not null, "icon" varchar, "summary" text, "description" text, "image" varchar, "features" text, "orderIndex" integer not null default ('0'), "isActive" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "testimonials" ("id" varchar not null, "clientName" text, "clientRole" text, "company" varchar, "content" text, "rating" integer not null default ('5'), "image" varchar, "isFeatured" tinyint(1) not null default ('0'), "orderIndex" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default '1', primary key ("id"));
CREATE TABLE IF NOT EXISTS "job_postings" ("id" varchar not null, "title" text, "slug" varchar not null, "departmentId" varchar, "location" text, "type" varchar not null default ('FULL_TIME'), "summary" text, "requirements" text, "benefits" text, "isActive" tinyint(1) not null default ('1'), "closingDate" datetime, "experience" text, "salary" text, "responsibilities" text, "created_at" datetime, "updated_at" datetime, foreign key("departmentId") references departments("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "news_articles" ("id" varchar not null, "title" text, "slug" varchar not null, "excerpt" text, "content" text, "coverImage" varchar, "publishedAt" datetime not null default (CURRENT_TIMESTAMP), "category" varchar not null, "tags" text, "authorId" varchar, "isFeatured" tinyint(1) not null default ('0'), "metaTitle" varchar, "metaDescription" text, "authorName" text, "gallery" text, "isTrending" tinyint(1) not null default ('0'), "readTime" text, "year" varchar, "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default '1', "videoUrl" varchar, foreign key("authorId") references employees("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "departments" ("id" varchar not null, "name" text, "description" text, "created_at" datetime, "updated_at" datetime, "slug" varchar, "isActive" tinyint(1) not null default '1', primary key ("id"));
CREATE TABLE IF NOT EXISTS "org_units" ("id" varchar not null, "title" text, "type" varchar not null default ('STAFF'), "parentId" varchar, "employeeId" varchar, "departmentId" varchar, "orderIndex" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default '1', foreign key("departmentId") references departments("id") on delete set null on update no action, foreign key("employeeId") references employees("id") on delete set null on update no action, foreign key("parentId") references org_units("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "partners" ("id" varchar not null, "name" text, "logoUrl" varchar not null, "website" varchar, "type" varchar not null default ('CLIENT'), "orderIndex" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default '1', primary key ("id"));
CREATE TABLE IF NOT EXISTS "employees" ("id" varchar not null, "name" varchar not null, "email" varchar, "phone" varchar, "image" varchar, "bio" text, "bioKm" text, "experience" varchar, "location" varchar, "locationKm" varchar, "specialization" varchar, "specializationKm" varchar, "role" varchar, "roleKm" varchar, "created_at" datetime, "updated_at" datetime, "user_id" integer, "isActive" tinyint(1) not null default '1', foreign key("user_id") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "project_categories" ("id" integer primary key autoincrement not null, "name" text not null, "slug" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime, "parent_id" integer, "isActive" tinyint(1) not null default '1', foreign key("parent_id") references "project_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "policies" ("id" varchar not null, "title" text not null, "slug" varchar not null, "content" text, "icon" varchar, "sort_order" integer not null default '0', "is_public" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "document_categories" ("id" integer primary key autoincrement not null, "name" text not null, "slug" varchar not null, "description" text, "parent_id" integer, "icon" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default '1', foreign key("parent_id") references "document_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "documents" ("id" varchar not null, "title" text, "description" text, "fileUrl" varchar not null, "fileSize" varchar, "fileType" varchar, "thumbnailUrl" varchar, "category" varchar not null, "departmentId" varchar, "isPublic" tinyint(1) not null default ('1'), "downloadCount" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "slug" varchar, "is_featured" tinyint(1) not null default ('0'), "document_category_id" integer, "isActive" tinyint(1) not null default '1', foreign key("departmentId") references departments("id") on delete set null on update no action, foreign key("document_category_id") references "document_categories"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "activity_log" ("id" integer primary key autoincrement not null, "log_name" varchar, "description" text not null, "subject_type" varchar, "subject_id" varchar, "causer_type" varchar, "causer_id" varchar, "properties" text, "created_at" datetime, "updated_at" datetime, "event" varchar, "batch_uuid" varchar);
CREATE TABLE IF NOT EXISTS "job_applications" ("id" varchar not null, "jobId" varchar, "applicantName" varchar not null, "email" varchar not null, "phone" varchar not null, "resumeUrl" varchar not null, "coverLetter" text, "status" varchar not null default ('PENDING'), "submittedAt" datetime not null default (CURRENT_TIMESTAMP), "created_at" datetime, "updated_at" datetime, foreign key("jobId") references job_postings("id") on delete cascade on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "methodology_steps" ("id" varchar not null, "title" text not null, "description" text not null, "icon" varchar not null default 'lucide-settings', "orderIndex" integer not null default '0', "isActive" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "projects" ("id" varchar not null, "title" text, "slug" varchar not null, "category" varchar, "status" varchar not null default ('ONGOING'), "location" text, "client" varchar, "completionDate" datetime, "description" text, "heroImage" varchar, "isFeatured" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "project_category_id" integer, "background" text, "objectives" text, "designConcept" text, "scopeContributions" text, "engineeringNarrative" text, "timeline" varchar, "scale" varchar, "isActive" tinyint(1) not null default ('1'), foreign key("project_category_id") references project_categories("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "milestones" ("id" varchar not null, "year" varchar not null, "title" text, "description" text, "image" varchar, "sortOrder" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "isActive" tinyint(1) not null default ('1'), "detailed_description" text, primary key ("id"));
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "system_settings_key_unique" on "system_settings" ("key");
CREATE UNIQUE INDEX "services_slug_unique" on "services" ("slug");
CREATE UNIQUE INDEX "job_postings_slug_unique" on "job_postings" ("slug");
CREATE UNIQUE INDEX "news_articles_slug_unique" on "news_articles" ("slug");
CREATE UNIQUE INDEX "departments_name_unique" on "departments" ("name");
CREATE UNIQUE INDEX "employees_email_unique" on "employees" ("email");
CREATE UNIQUE INDEX "departments_slug_unique" on "departments" ("slug");
CREATE UNIQUE INDEX "project_categories_slug_unique" on "project_categories" ("slug");
CREATE UNIQUE INDEX "policies_slug_unique" on "policies" ("slug");
CREATE UNIQUE INDEX "document_categories_slug_unique" on "document_categories" ("slug");
CREATE INDEX "activity_log_log_name_index" on "activity_log" ("log_name");
CREATE INDEX "causer" on "activity_log" ("causer_type", "causer_id");
CREATE INDEX "subject" on "activity_log" ("subject_type", "subject_id");
CREATE UNIQUE INDEX "projects_slug_unique" on "projects" ("slug");
CREATE INDEX "idx_documents_slug" on "documents" ("slug");
CREATE INDEX "idx_documents_active_public" on "documents" ("isActive", "isPublic");
CREATE INDEX "idx_documents_category_id" on "documents" ("document_category_id");
CREATE INDEX "idx_document_categories_active" on "document_categories" ("isActive");
CREATE INDEX "idx_projects_slug" on "projects" ("slug");
CREATE INDEX "idx_projects_active" on "projects" ("isActive");
CREATE INDEX "idx_news_articles_slug" on "news_articles" ("slug");
CREATE INDEX "idx_news_articles_active" on "news_articles" ("isActive");
CREATE INDEX "idx_services_slug" on "services" ("slug");
CREATE INDEX "idx_services_active" on "services" ("isActive");
CREATE INDEX "idx_job_postings_slug" on "job_postings" ("slug");
CREATE INDEX "idx_job_postings_active" on "job_postings" ("isActive");
CREATE INDEX "idx_project_categories_active" on "project_categories" ("isActive");
CREATE INDEX "idx_milestones_active_sort" on "milestones" ("isActive", "sortOrder");
CREATE INDEX "idx_org_units_active_parent_order" on "org_units" ("isActive", "parentId", "orderIndex");
COMMIT;
